fn supported_token_program(p:&Pubkey)->bool{*p==TOKEN_PROGRAM||*p==TOKEN_2022_PROGRAM}
// Reject every extension that can alter amounts, transfer authorization, or custody.
fn token_extensions(d:&[u8],p:&Pubkey,mint:Option<&Pubkey>)->ProgramResult{
 let base=if mint.is_some(){82}else{165};
 if !supported_token_program(p)||d.len()<base{return Err(err(AntError::InvalidToken));}
 if *p==TOKEN_PROGRAM{return if d.len()==base{Ok(())}else{Err(err(AntError::InvalidToken))};}
 if d.len()==base{return Ok(());}
 if d.len()<166||d[165]!=if mint.is_some(){1}else{2}||mint.is_some()&&d[82..165].iter().any(|b|*b!=0){return Err(err(AntError::InvalidToken));}
 let mut at=166;let mut seen=0u32;
 while at<d.len(){if d[at..].iter().all(|v|*v==0){break;}if d.len()-at<4{return Err(err(AntError::InvalidToken));}
 let t=u16::from_le_bytes(d[at..at+2].try_into().unwrap());let n=u16::from_le_bytes(d[at+2..at+4].try_into().unwrap()) as usize;at+=4;
 if n>d.len()-at||t>=32||seen&(1u32<<t)!=0{return Err(err(AntError::InvalidToken));}seen|=1u32<<t;
 let value=&d[at..at+n];match mint{
 Some(key)=>{if !((t==18&&n==64&&value[..32].iter().all(|b|*b==0)||t==19&&n>=80)&&value[32..64]==key.to_bytes()){return Err(err(AntError::InvalidToken));}},
 None=>{if t!=7||n!=0{return Err(err(AntError::InvalidToken));}}
 }at+=n;}
 Ok(())
}
