fn claim(program_id:&Pubkey,accounts:&[AccountInfo],rd:&mut Reader)->ProgramResult{rd.done()?;let wallet=&accounts[0];let round_a=&accounts[1];let capsule_a=&accounts[2];signer(wallet)?;writable(round_a)?;writable(capsule_a)?;writable(wallet)?;let mut r=load_round(program_id,round_a)?;let mut cap=load_capsule(program_id,capsule_a)?;let now=Clock::get()?.unix_timestamp;if now<r.reveal_end||now>=r.claim_end{return Err(err(AntError::Deadline));}if cap.wallet!=*wallet.key||cap.round_id!=r.id{return Err(err(AntError::WrongAuthority));}if r.rolled||!cap.revealed{return Err(err(AntError::InvalidState));}if cap.claimed{return Err(err(AntError::Replay));}let question_pool=r.reward_pool/2;let mut reward=0u64;for i in 0..2{if r.results[i]!=CANCELED_BUCKET&&cap.answers[i]==r.results[i]&&r.total_correct[i]>0{let share=(question_pool as u128).checked_mul(cap.deposit as u128).ok_or(err(AntError::Arithmetic))?/(r.total_correct[i] as u128);reward=reward.checked_add(u64::try_from(share).map_err(|_|err(AntError::Arithmetic))?).ok_or(err(AntError::Arithmetic))?;}}r.reward_paid=r.reward_paid.checked_add(reward).ok_or(err(AntError::Arithmetic))?;if r.reward_paid>r.reward_pool{return Err(err(AntError::Arithmetic));}if reward>0{let from=round_a.lamports().checked_sub(reward).ok_or(err(AntError::Arithmetic))?;let to=wallet.lamports().checked_add(reward).ok_or(err(AntError::Arithmetic))?;**round_a.try_borrow_mut_lamports()?=from;**wallet.try_borrow_mut_lamports()?=to;}cap.claimed=true;cap.reward_paid=reward;save_round(round_a,&r)?;save_capsule(capsule_a,&cap)}
fn rollover(program_id:&Pubkey,accounts:&[AccountInfo],rd:&mut Reader)->ProgramResult{rd.done()?;let source_a=&accounts[0];let target_a=&accounts[1];writable(source_a)?;writable(target_a)?;let mut source=load_round(program_id,source_a)?;let mut target=load_round(program_id,target_a)?;let now=Clock::get()?.unix_timestamp;if now<source.claim_end||now>=target.entry_open{return Err(err(AntError::Deadline));}if source.rolled||source.config!=target.config{return Err(err(AntError::Replay));}let amount=source.reward_pool.checked_sub(source.reward_paid).ok_or(err(AntError::Arithmetic))?;target.reward_pool=target.reward_pool.checked_add(amount).ok_or(err(AntError::Arithmetic))?;source.rolled=true;if amount>0{let from=source_a.lamports().checked_sub(amount).ok_or(err(AntError::Arithmetic))?;let to=target_a.lamports().checked_add(amount).ok_or(err(AntError::Arithmetic))?;**source_a.try_borrow_mut_lamports()?=from;**target_a.try_borrow_mut_lamports()?=to;}save_round(source_a,&source)?;save_round(target_a,&target)}

