// Atomic per-round full custody sweep. The first sweep freezes the entire
// protocol; additional rounds/sweeps are resumable transactions under that freeze.
// Accounts: administrator, config, round, vault, mint, owner ATA,
// vault authority, legacy token program, system program.
fn emergency_custody(p:&Pubkey,a:&[AccountInfo],rd:&mut Reader,restore:bool)->ProgramResult{
 signer(&a[0])?;for i in [0,1,2,3,5]{writable(&a[i])?;}
 let mut c=load_config(p,&a[1])?;let mut r=load_round(p,&a[2])?;
 if *a[0].key!=c.administrator{return Err(err(AntError::WrongAuthority));}
 if r.config!=*a[1].key||r.deposit_vault!=*a[3].key||*a[4].key!=c.mint||*a[7].key!=c.token_program||!a[7].executable||*a[8].key!=system_program::id(){return Err(err(AntError::InvalidAccount));}
 let nonce=rd.u64()?;let(max_tokens,max_sol)=if restore{(rd.u64()?,rd.u64()?)}else{(0,0)};rd.done()?;
 let id=r.id.to_le_bytes();let(authority,bump)=Pubkey::find_program_address(&[b"vault-authority",&id],p);
 let ata_program=solana_program::pubkey!("ATokenGPvbdGVxr1b2hvZbsiqW5xWH25efTNsLJA8knL");
 let destination=Pubkey::find_program_address(&[c.administrator.as_ref(),c.token_program.as_ref(),c.mint.as_ref()],&ata_program).0;
 if *a[6].key!=authority||*a[5].key!=destination{return Err(err(AntError::InvalidAccount));}
 let(vm,vo,tokens)=token_account(&a[3],&c.token_program)?;let(dm,owner,source_tokens)=token_account(&a[5],&c.token_program)?;
 if vm!=c.mint||vo!=authority||dm!=c.mint||owner!=c.administrator{return Err(err(AntError::InvalidToken));}
 let decimals=mint_decimals(&a[4],&c.token_program)?;
 let rent=Rent::get()?.minimum_balance(ROUND_LEN);let sol=a[2].lamports().saturating_sub(rent);
 let now=Clock::get()?.unix_timestamp;
 if restore{
  if !c.paused||!r.emergency{return Err(err(AntError::InvalidState));}
  if nonce!=r.recovery_nonce{return Err(err(AntError::Replay));}
  let token_floor=r.total_deposited.checked_sub(r.withdrawn).ok_or(err(AntError::Arithmetic))?;
  let sol_floor=if r.rolled{0}else{r.reward_pool.checked_sub(r.reward_paid).ok_or(err(AntError::Arithmetic))?};
  let token_target=r.token_target.max(token_floor);let sol_target=r.sol_target.max(sol_floor);
  let token_amount=token_target.saturating_sub(tokens);
  let required_lamports=rent.checked_add(sol_target).ok_or(err(AntError::Arithmetic))?;
  let sol_amount=required_lamports.saturating_sub(a[2].lamports());
  if token_amount>max_tokens||sol_amount>max_sol||token_amount>source_tokens||sol_amount>a[0].lamports(){return Err(err(AntError::InvalidState));}
  if token_amount>0{token_transfer_checked(&a[5],&a[4],&a[3],&a[0],&a[7],token_amount,decimals,None)?;}
  if sol_amount>0{invoke(&system_instruction::transfer(a[0].key,a[2].key,sol_amount),&[a[0].clone(),a[2].clone(),a[8].clone()])?;}
  if token_account(&a[3],&c.token_program)?.2<token_target||a[2].lamports()<required_lamports{return Err(err(AntError::InvalidState));}
  r.emergency=false;c.active_recoveries=c.active_recoveries.checked_sub(1).ok_or(err(AntError::Arithmetic))?;
  solana_program::msg!("ANT_RECOVERY restore round={} nonce={} tokens={} lamports={}",r.id,nonce,token_amount,sol_amount);
 }else{
  if nonce!=r.recovery_nonce.checked_add(1).ok_or(err(AntError::Arithmetic))?{return Err(err(AntError::Replay));}
  if !c.paused{c.paused=true;c.paused_at=now;c.recovery_epoch=c.recovery_epoch.checked_add(1).ok_or(err(AntError::Arithmetic))?;}
  if !r.emergency{c.active_recoveries=c.active_recoveries.checked_add(1).ok_or(err(AntError::Arithmetic))?;}
  // Targets are maxima, not cumulative sweep totals: returning and sweeping
  // the same funds cannot inflate restoration debt. Liabilities are untouched.
  r.token_target=tokens.max(r.total_deposited.saturating_sub(r.withdrawn)).max(if r.emergency{r.token_target}else{0});
  r.sol_target=sol.max(if r.rolled{0}else{r.reward_pool.saturating_sub(r.reward_paid)}).max(if r.emergency{r.sol_target}else{0});
  source_tokens.checked_add(tokens).ok_or(err(AntError::Arithmetic))?;
  let to=a[0].lamports().checked_add(sol).ok_or(err(AntError::Arithmetic))?;
  if tokens>0{let bs=[bump];token_transfer_checked(&a[3],&a[4],&a[5],&a[6],&a[7],tokens,decimals,Some(&[b"vault-authority",&id,&bs]))?;}
  let remaining=a[2].lamports().checked_sub(sol).ok_or(err(AntError::Arithmetic))?;
  **a[2].try_borrow_mut_lamports()?=remaining;
  **a[0].try_borrow_mut_lamports()?=to;
  r.recovery_nonce=nonce;r.emergency=true;r.swept_token=tokens;r.swept_sol=sol;r.recovery_at=now;
  solana_program::msg!("ANT_RECOVERY rescue round={} nonce={} tokens={} lamports={} token_target={} sol_target={}",r.id,nonce,tokens,sol,r.token_target,r.sol_target);
 }
 save_config(&a[1],&c)?;save_round(&a[2],&r)
}
fn resume(p:&Pubkey,a:&[AccountInfo],rd:&mut Reader)->ProgramResult{
 signer(&a[0])?;writable(&a[1])?;let mut c=load_config(p,&a[1])?;
 if *a[0].key!=c.administrator{return Err(err(AntError::WrongAuthority));}
 let expected_epoch=rd.u64()?;rd.done()?;
 if !c.paused||c.active_recoveries!=0||expected_epoch!=c.recovery_epoch{return Err(err(AntError::InvalidState));}
 let elapsed=Clock::get()?.unix_timestamp.checked_sub(c.paused_at).ok_or(err(AntError::Arithmetic))?;
 c.paused_seconds=c.paused_seconds.checked_add(u64::try_from(elapsed).map_err(|_|err(AntError::Arithmetic))?).ok_or(err(AntError::Arithmetic))?;
 c.paused=false;save_config(&a[1],&c)?;
 solana_program::msg!("ANT_RECOVERY resume paused_seconds={}",c.paused_seconds);Ok(())
}

