// Mode 3 captures authenticated sponsored updates during a bounded window.
// Numeric observations are read only from the pinned receiver-owned account.
fn push_price_data(d:&[u8],feed:&[u8;32],bps:u16)->Result<PythPrice,ProgramError>{
 if d.len()<133||d[0..8]!=PYTH_PRICE_UPDATE_V2_DISCRIMINATOR||d[40]!=1||&d[41..73]!=feed{return Err(err(AntError::InvalidAccount));}
 let p=PythPrice{price:i64::from_le_bytes(d[73..81].try_into().unwrap()),conf:u64::from_le_bytes(d[81..89].try_into().unwrap()),exponent:i32::from_le_bytes(d[89..93].try_into().unwrap()),publish_time:i64::from_le_bytes(d[93..101].try_into().unwrap()),prev_publish_time:i64::from_le_bytes(d[101..109].try_into().unwrap())};
 if p.price<=0||p.exponent < -18||p.exponent>18||p.prev_publish_time>=p.publish_time||(p.conf as u128)*10_000>(p.price as u128)*(bps as u128){return Err(err(AntError::InvalidState));}Ok(p)
}
fn push_window(p:&PythPrice,boundary:i64,now:i64)->ProgramResult{let end=boundary.checked_add(PUSH_WINDOW_SECONDS as i64).ok_or(err(AntError::Arithmetic))?;if now<boundary||now>end||p.publish_time<boundary||p.publish_time>end||p.publish_time>now{return Err(err(AntError::Deadline));}Ok(())}
fn capture_boundary(program_id:&Pubkey,a:&[AccountInfo],rd:&mut Reader)->ProgramResult{
 let q=rd.u8()?;let b=rd.u8()?;rd.done()?;if q>1||b>1{return Err(err(AntError::InvalidInstruction));}signer(&a[0])?;writable(&a[0])?;writable(&a[3])?;
 let c=load_config(program_id,&a[1])?;if c.settlement_mode!=3{return Err(err(AntError::ProductionSettlementDisabled));}let r=load_round(program_id,&a[2])?;
 if r.config!=*a[1].key||*a[4].key!=c.oracle_sources[q as usize]||*a[4].owner!=c.oracle_owner{return Err(err(AntError::InvalidAccount));}
 let boundary=if b==0{r.entry_close}else{r.observation_end};let now=Clock::get()?.unix_timestamp;let source=a[4].try_borrow_data()?;let p=push_price_data(&source,&c.oracle_feeds[q as usize],c.oracle_max_confidence_bps)?;push_window(&p,boundary,now)?;
 let id=r.id.to_le_bytes();let qb=[q,b];let(expected,bump)=Pubkey::find_program_address(&[b"checkpoint",&id,&qb],program_id);if *a[3].key!=expected{return Err(err(AntError::InvalidAccount));}if a[3].owner==program_id{return Err(err(AntError::Replay));}
 let source_hash=hashv(&[a[4].key.as_ref(),a[4].owner.as_ref(),&source]).to_bytes();drop(source);
 create_pda(program_id,&a[0],&a[3],&a[5],&[b"checkpoint",&id,&qb],bump,CHECKPOINT_LEN)?;
 let mut d=a[3].try_borrow_mut_data()?;d.fill(0);d[0]=4;d[1]=1;d[2]=bump;d[3]=q;d[4]=b;d[5..13].copy_from_slice(&id);d[13..45].copy_from_slice(a[1].key.as_ref());d[45..77].copy_from_slice(a[2].key.as_ref());d[77..109].copy_from_slice(a[4].key.as_ref());d[109..141].copy_from_slice(&c.oracle_feeds[q as usize]);d[141..149].copy_from_slice(&boundary.to_le_bytes());d[149..157].copy_from_slice(&now.to_le_bytes());d[157..165].copy_from_slice(&p.price.to_le_bytes());d[165..173].copy_from_slice(&p.conf.to_le_bytes());d[173..177].copy_from_slice(&p.exponent.to_le_bytes());d[177..185].copy_from_slice(&p.publish_time.to_le_bytes());d[185..193].copy_from_slice(&p.prev_publish_time.to_le_bytes());d[193..225].copy_from_slice(&source_hash);
 solana_program::msg!("ANT_CHECKPOINT round={} question={} boundary={} publish={}",r.id,q,b,p.publish_time);Ok(())
}
fn checkpoint_price(program_id:&Pubkey,a:&AccountInfo,config:&Pubkey,round:&Pubkey,c:&Config,r:&Round,q:u8,b:u8)->Result<PythPrice,ProgramError>{
 owned(a,program_id)?;let id=r.id.to_le_bytes();let qb=[q,b];let expected=Pubkey::find_program_address(&[b"checkpoint",&id,&qb],program_id).0;let d=a.try_borrow_data()?;let target=if b==0{r.entry_close}else{r.observation_end};
 if *a.key!=expected||d.len()!=CHECKPOINT_LEN||d[0]!=4||d[1]!=1||d[3]!=q||d[4]!=b||d[5..13]!=id||d[13..45]!=config.to_bytes()||d[45..77]!=round.to_bytes()||d[77..109]!=c.oracle_sources[q as usize].to_bytes()||d[109..141]!=c.oracle_feeds[q as usize]||i64::from_le_bytes(d[141..149].try_into().unwrap())!=target{return Err(err(AntError::InvalidAccount));}
 let p=PythPrice{price:i64::from_le_bytes(d[157..165].try_into().unwrap()),conf:u64::from_le_bytes(d[165..173].try_into().unwrap()),exponent:i32::from_le_bytes(d[173..177].try_into().unwrap()),publish_time:i64::from_le_bytes(d[177..185].try_into().unwrap()),prev_publish_time:i64::from_le_bytes(d[185..193].try_into().unwrap())};push_window(&p,target,i64::from_le_bytes(d[149..157].try_into().unwrap()))?;Ok(p)
}

